import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.DMXcdKmJ.js";const f=JSON.parse('{"title":"版本记录","description":"查看 InduFrame 当前 v1.0 版本、已测试系统及使用手册的适用范围。","frontmatter":{"title":"版本记录","description":"查看 InduFrame 当前 v1.0 版本、已测试系统及使用手册的适用范围。","status":"reviewed","kind":"reference"},"headers":[],"relativePath":"zh/releases/index.md","filePath":"zh/版本说明/版本记录.md"}'),l={name:"zh/releases/index.md"};function n(d,a,o,s,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="版本记录" tabindex="-1">版本记录 <a class="header-anchor" href="#版本记录" aria-label="Permalink to &quot;版本记录&quot;">​</a></h1><p>当前版本为 <strong>v1.0</strong>。使用前请先核对交付的安装包版本；需要更新时，先向交付人员确认安装包是否适用于现有平台。</p><h2 id="v1-0-当前版本" tabindex="-1">v1.0（当前版本） <a class="header-anchor" href="#v1-0-当前版本" aria-label="Permalink to &quot;v1.0（当前版本）&quot;">​</a></h2><h3 id="可以从本手册完成什么" tabindex="-1">可以从本手册完成什么 <a class="header-anchor" href="#可以从本手册完成什么" aria-label="Permalink to &quot;可以从本手册完成什么&quot;">​</a></h3><ul><li><a href="/induframe-docs/zh/installation/install.html">安装平台</a>：使用完整安装包，按提示设置访问地址和平台管理员。</li><li><a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>：设置默认组织管理员密码，再进入工作台。</li><li><a href="/induframe-docs/zh/guide/login.html">登录与退出</a>：区分平台管理入口和组织使用的公共入口。</li><li><a href="/induframe-docs/zh/guide/project-files.html">查看和上传工程文件</a>：在工程资源页核对上传、打开、复制地址与移除的结果。</li><li><a href="/induframe-docs/zh/installation/uninstall.html">卸载平台</a>：明确选择保留数据或删除数据，并核对卸载结果。</li><li><a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>：在满足原服务器、原数据和同一完整安装包等条件时重新安装。</li></ul><p>安装完成后，实际工程中的采集、计算、报警等功能还需要按业务需求配置，并分别确认运行结果。</p><h3 id="已测试系统" tabindex="-1">已测试系统 <a class="header-anchor" href="#已测试系统" aria-label="Permalink to &quot;已测试系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>当前结论</th></tr></thead><tbody><tr><td><strong>Ubuntu 24</strong></td><td><strong>目前已测试，优先推荐</strong></td></tr><tr><td>其他系统</td><td>尚未测试，暂不作为已验证环境推荐</td></tr></tbody></table><p>安装包与服务器架构仍需匹配。不同系统、不同架构和不同证书条件不能直接套用同一个测试结论。详细准备条件见<a href="/induframe-docs/zh/reference/system-requirements.html">系统与安装要求</a>。</p><h3 id="使用时要注意" tabindex="-1">使用时要注意 <a class="header-anchor" href="#使用时要注意" aria-label="Permalink to &quot;使用时要注意&quot;">​</a></h3><ul><li>删除数据无法撤回；保留数据卸载也不能代替备份。</li><li>保留数据重装限于原服务器、原数据和原安装包，不是迁移或任意跨版本更新工具。</li><li>完整安装包统一执行 <code>./install.sh</code>；只有明确提供小型补丁包时，才按其说明使用 <code>./update.sh</code>。</li></ul><p>后续版本将在本页记录面向使用者的变化、适用范围和注意事项。当前使用指南从<a href="/induframe-docs/zh/start/">安装并进入平台</a>开始。</p>',12)])])}const m=e(l,[["render",n]]);export{f as __pageData,m as default};
